# POST /api/sheets/{sheetId}/periods — add a period: a name and a from and to date, both inclusive. An empty name,
# a date that is not yyyy-MM-dd, a to-date before the from-date, a name already on the sheet (case and outer spaces
# ignored) or dates overlapping another period of the sheet is a 400 and writes nothing. Responds 201 with the
# period as stored.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: check
check:
  class: net.officefloor.hq.app.period.CheckNewPeriod
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.period.AddPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriodCreated
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the name is not empty, the from and to dates are yyyy-MM-dd, and the to-date is not before the
 *  from-date. */
public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<PeriodValues> values) throws InvalidPeriodException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPeriodException("A period needs a name");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date may not be before the from-date");
        }
        values.set(new PeriodValues(name, from, to, request.by() == null ? "" : request.by().trim()));
    }

    private static LocalDate date(String text, String which) throws InvalidPeriodException {
        try {
            return LocalDate.parse(text == null ? "" : text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date yyyy-MM-dd");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** A period being added may not take a name already on the sheet, nor share a day with another of its periods. */
public class CheckNewPeriod {
    public void check(@PathVariable("sheetId") String sheetId, @Val PeriodValues values, PeriodRepository periods)
            throws InvalidPeriodException {
        String sheet = sheetId.trim();
        if (periods.nameTaken(sheet, values.name())) {
            throw new InvalidPeriodException("A period named " + values.name() + " is already on the sheet");
        }
        if (periods.overlaps(sheet, values.from(), values.to())) {
            throw new InvalidPeriodException("The period overlaps another period of the sheet");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Stores the new period on the sheet. */
public class AddPeriod {
    public void add(@PathVariable("sheetId") String sheetId, @Val PeriodValues values, PeriodRepository periods,
            Out<Period> period) {
        period.set(periods.add(sheetId.trim(), values.name(), values.from(), values.to()));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Writes PERIOD_ADDED to the audit file once the period is stored. */
public class RecordPeriodAdded {
    public void record(@Val Period period, @Val PeriodValues values, Audit audit) {
        audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + values.by() + " period=" + period.name()
                + " from=" + period.from() + " to=" + period.to());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class RespondWithPeriodCreated {
    public void respond(@Val Period period, PeriodRepository periods, ObjectResponse<ResponseEntity<PeriodResponse>> response) {
        response.send(new ResponseEntity<>(PeriodResponse.from(period, periods), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.period;

/** Body of adding a period: its name, from and to dates (yyyy-MM-dd), and who adds it. */
public record PeriodRequest(String name, String from, String to, String by) {
}
package net.officefloor.hq.app.period;

/** A period that cannot be added: an empty name, a date that is not yyyy-MM-dd, a to-date before its from-date,
 *  a name already on the sheet, or dates overlapping another period of the sheet. */
public class InvalidPeriodException extends Exception {
    public InvalidPeriodException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPeriod {
    public void handle(@Parameter InvalidPeriodException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The stored periods of each sheet. */
@Repository
public class PeriodRepository {

    private static final String COLUMNS = "id, sheet_id, name, from_date, to_date, closed, closed_total";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date, id",
                PeriodRepository::map, sheetId);
    }

    /** Whether the name is already a period's on the sheet, case and outer spaces ignored. */
    public boolean nameTaken(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
                Integer.class, sheetId, name.trim());
        return n != null && n > 0;
    }

    /** Whether any period of the sheet shares a day with the dates from..to, both inclusive. */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(to), Date.valueOf(from));
        return n != null && n > 0;
    }

    /** A period of the sheet by id, or null when it has none. */
    public Period find(String sheetId, long id) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND id = ?",
                PeriodRepository::map, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The period of the sheet whose dates contain the date, or null when none does. */
    public Period containing(String sheetId, LocalDate date) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                PeriodRepository::map, sheetId, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether a closed period of the sheet contains the date. */
    public boolean closedOn(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed = TRUE "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Closes the period with its fixed due-total, but only while it is still open; false when it was not. */
    public boolean close(Period period, BigDecimal total) {
        return jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND id = ? AND closed = FALSE",
                total, period.sheetId(), period.id()) == 1;
    }

    /** Fixes each person's due-total for the period, as it is closed. */
    public void fixPersonTotals(Period period, Map<Long, BigDecimal> totals) {
        for (Map.Entry<Long, BigDecimal> e : totals.entrySet()) {
            jdbc.update("INSERT INTO period_person_total (sheet_id, period_id, person_id, total) VALUES (?, ?, ?, ?)",
                    period.sheetId(), period.id(), e.getKey(), e.getValue());
        }
    }

    /** The fixed due-total of each person for the closed period, by person id. */
    public Map<Long, BigDecimal> personTotals(Period period) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_id = ? ORDER BY person_id",
                (ResultSet rs) -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total").setScale(2));
                }, period.sheetId(), period.id());
        return totals;
    }

    /** Reopens the period, dropping its fixed due-totals, but only while it is closed; false when it was not. */
    public boolean reopen(Period period) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_id = ?", period.sheetId(), period.id());
        return jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND id = ? AND closed = TRUE",
                period.sheetId(), period.id()) == 1;
    }

    /** Stores a new period and returns it with its id. */
    public Period add(String sheetId, String name, LocalDate from, LocalDate to) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update((con) -> {
            var ps = con.prepareStatement("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setDate(3, Date.valueOf(from));
            ps.setDate(4, Date.valueOf(to));
            return ps;
        }, keys);
        return new Period(keys.getKey().longValue(), sheetId, name, from, to, false, null);
    }

    private static Period map(ResultSet rs, int n) throws SQLException {
        BigDecimal total = rs.getBigDecimal("closed_total");
        return new Period(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), total == null ? null : total.setScale(2));
    }
}
